(function(){function QRCode(el,options){var container=(typeof el==='string')?document.getElementById(el):el;if(!container)return;var text=(options&&options.text)||window.location.href;var size=(options&&options.width)||200;var img=document.createElement('img');img.alt='QR code';img.width=size;img.height=size;img.style.background='#fff';img.style.border='1px solid #ccc';img.style.boxShadow='0 2px 8px rgba(0,0,0,0.18)';img.style.display='block';img.src='https://api.qrserver.com/v1/create-qr-code/?size='+size+'x'+size+'&data='+encodeURIComponent(text);container.innerHTML='';container.appendChild(img);}window.QRCode=QRCode;})();